import { B, tag, teach, withShapes } from '../blocks.js';

export const MODULE = { id: 'b1b2-module-10', course: 'b2', title: 'Suhted ja konfliktid', level: 'B2', design: 'v2', template: 'v4' };

// an exam part header carries the goal of its part: b2/lessonGoals.test.js asks every non-text block of a B2 sheet for one
// of the lesson's goals, and the header has none of its own (B.examPart: goal '')
const PART = (id, skill, o) => ({ ...B.examPart(id, skill, o), goal: ['R', 'L'].includes(skill) ? 'g_read' : 'g_use' });
// the examiner's set with its own instruction (B.examiner's default wording is shared by every module: finalShape V7)
const withInstruction = (b, instruction) => ({ ...b, data: { ...b.data, instruction } });

// used by the check lesson 050
const TR = (id, title, instruction, rows) => B.translation(id, title, instruction, rows);

